		dst = append(dst, make([]float32, 32)...)
		out := dst[lo:]
		for j := 0; j < 16; j++ {
			xh0 := byte((qh >> j << 4) & 0x10)
			xh1 := byte((qh >> (j + 12)) & 0x10)
			x0 := blk[8+j]&0x0F | xh0
			x1 := blk[8+j]>>4 | xh1
			out[j] = float32(x0)*d + m
			out[j+16] = float32(x1)*d + m
