			name string
			src  []float32
			n    int
		}{
			{"attn_qkv", w.QKV, cw},
			{"attn_gate", w.Z, c.Inner},
			{"ssm_alpha", w.Alpha, c.NHeadV},
			{"ssm_beta", w.Beta, c.NHeadV},
