		g.bank.WriteUint16At(int(g.layers[i].qkv), qkv)

		out := make([]uint16, c.NEmbd*c.Inner)
		tileB(out, w.Out, c.NEmbd, c.Inner, func(r int) int { return r })
		g.bank.WriteUint16At(int(g.layers[i].out), out)
	}
	return nil
}

