#version 450

#extension GL_KHR_cooperative_matrix : enable
#extension GL_KHR_memory_scope_semantics : enable
#extension GL_KHR_shader_subgroup_basic : enable
#extension GL_EXT_shader_16bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
#extension GL_EXT_control_flow_attributes : enable

// The grouped expert GEMM: 35.7% of llama.cpp's prefill graph, 97% of this
// checkpoint's parameters, and the last block of the model without a kernel
// (LLM.md L5b).
//
// **It reads the checkpoint's own quantised blocks.** Every other GEMM in
// this vertical takes a B operand the host has dequantised to halves and
// packed into §2.8 fragment tiles. That cannot happen here: one layer's three
// expert banks are 2.52 billion weights, 5.03 GB at fp16 and 241 GB across
// the model, against 1.57 GB and 75 GB as they ship. So the bank is staged
// **verbatim** — Q4_K and Q5_K for gate and up, Q5_1 or Q8_0 for down, Q8_0
// for the shared expert — and each workgroup unpacks its own BN x BK slab
// into LDS per K-step, which is §2.2's arrangement for the same reason it
// gave: a cooperative-matrix fragment's lane layout is not exposed, so
// nibbles cannot be unpacked into registers and declared a fragment.
//
// Two modes, and both of them fuse what llama.cpp spends a dispatch on:
//
//   MODE 0   gate and up for one (expert, row block), `silu(gate)*up` on the
//            accumulators.  The [rows, 640] pair never exists: the reference
//            writes `ffn_moe_gate` and `ffn_moe_up` and then reads them back
//            through `ggml_swiglu_split`.
//   MODE 1   down, times the row's routing weight, scattered to its
//            (token, slot).  `ffn_moe_weighted` never exists either.
//
// **The A operand of MODE 0 is gathered and the A operand of MODE 1 is not**,
// and that asymmetry is the permutation paying for itself. A routed row is
// some token's row of the block input, so MODE 0 stages BM scattered rows
// into LDS; what it writes is indexed by *permutation position*, so MODE 1's
// rows are contiguous and it loads them straight out of the fp16 arena with
// no gather at all. The scatter happens once, in MODE 1's epilogue, where it
// is a store that had to happen anyway.
//
// **The tail of a tile is guarded, which is why the epilogue goes through
// LDS.** L5a-4 measured the routing: 274 of 512 experts touched at a
// 512-token ubatch and 273 of them with fewer than 19 rows, so most tiles are
// mostly padding and the padding must not write — an expert's rows are
// immediately followed by another expert's. A cooperative-matrix store covers
// sixteen rows at once and cannot be masked, so the accumulators go to LDS
// and the rows come out one at a time under a bound. That is the same
// argument llm_gemm.comp's MODE 1 makes for its collapse, for a different
// reason.

#define MOE_QBANK
#include "llm_common.glsl"

#ifndef MODE
#define MODE 0      // 0 = gate/up + swiglu, 1 = down + weight + scatter
#endif
// The quantised format of this build's B. The bank ships as four of them and
// which one a tensor is, is a fact about the layer: `ffn_down_exps` is Q5_1 on
// 43 of the 48 layers and Q8_0 on the other five, gate and up are Q4_K except
// on layer 2 where they are Q5_K, and the shared expert is Q8_0 everywhere.
#define FMT_Q4_K 0
#define FMT_Q5_K 1
#define FMT_Q5_1 2
#define FMT_Q8_0 3
#ifndef QFMT
#define QFMT FMT_Q4_K
#endif
#ifndef WM
#define WM 2        // accumulator tiles, M direction
#endif
#ifndef WN
#define WN 4        // accumulator tiles, N direction
#endif

#define TILE 16
#define BM (WM * TILE)
#define BN (WN * TILE)
// One K-step is 32 elements, which is not a tuning choice: it is exactly one
// Q5_1 or Q8_0 block, and exactly one half of one Q4_K/Q5_K 64-element group,
// so a lane's slab of a row is one aligned block whose scale it reads once.
#define BK 32
#define BK_TILES (BK / TILE)
#define WAVE 64

#if BN != WAVE
#error "llm_moe_gemm stages one B row per lane"
#endif

layout(local_size_x = WAVE) in;

// §2.2's LDS_PAD, which it measured at 1.68-1.83x: a BK-half slab row is 64 B
// and 32 LDS banks rotate every 128 B, so an unpadded 16-row fragment load
// hits one bank many times over.
#define LDS_PAD 8
#define LDS_ROW (BK + LDS_PAD)

#if MODE == 0
shared float16_t sB0[BN * LDS_ROW];
shared float16_t sB1[BN * LDS_ROW];
shared float16_t sA[BM * LDS_ROW];
#else
shared float16_t sB0[BN * LDS_ROW];
#endif
shared float sC[BM * BN];

#define FRAG_A_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseA>
#define FRAG_B_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseB>
#define ACC_T coopmat<float, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>

// ---- The formats. Each is stated as "bytes a block covers" and "elements a
// block covers", so a row's byte length is (K / QK) * QB and nothing below
// has to know which axis it is walking.
#if QFMT == FMT_Q4_K
#define QK 256u
#define QB 144u
#elif QFMT == FMT_Q5_K
#define QK 256u
#define QB 176u
#elif QFMT == FMT_Q5_1
#define QK 32u
#define QB 24u
#else
#define QK 32u
#define QB 34u
#endif

uint qbyte(uint b) { return (qbank[b >> 2] >> ((b & 3u) * 8u)) & 0xFFu; }

float qhalf(uint b) { return unpackHalf2x16(qbyte(b) | (qbyte(b + 1u) << 8u)).x; }

#if QFMT == FMT_Q4_K || QFMT == FMT_Q5_K
// ggml's get_scale_min_k4: eight 6-bit scale/min pairs in twelve bytes. The
// first four are plain fields; the last four take their low nibble from bytes
// 8..11 and their top two bits from the spare bits of bytes 0..7.
void scaleMinK4(uint j, uint sbase, out uint sc, out uint mn) {
    if (j < 4u) {
        sc = qbyte(sbase + j) & 63u;
        mn = qbyte(sbase + j + 4u) & 63u;
    } else {
        uint a = qbyte(sbase + j + 4u);
        sc = (a & 0xFu) | ((qbyte(sbase + j - 4u) >> 6) << 4);
        mn = (a >> 4) | ((qbyte(sbase + j) >> 6) << 4);
    }
}
#endif

// dequantSlab writes the BK elements of bank row `row` starting at element
// `k0` into `dst` at `col * LDS_ROW`. One lane per output column, so the
// scale and min of the block are read once for the whole slab.
#define DEQUANT_SLAB(NAME, DST)                                                                 \
void NAME(uint bankBase, uint row, uint k0, uint col) {                                         \
    uint rb = bankBase + row * ((pc.gemmK / QK) * QB);                                          \
    uint dst = col * LDS_ROW;                                                                   \
    DEQUANT_BODY(DST)                                                                           \
}

#if QFMT == FMT_Q4_K
#define DEQUANT_BODY(DST)                                                                       \
    uint within = k0 & 255u;                                                                    \
    uint g = within >> 6;                                                                       \
    uint sub = (within >> 5) & 1u;                                                              \
    uint blk = rb + (k0 >> 8) * 144u;                                                           \
    float d = qhalf(blk);                                                                       \
    float dmin = qhalf(blk + 2u);                                                               \
    uint sc, mn;                                                                                \
    scaleMinK4(2u * g + sub, blk + 4u, sc, mn);                                                 \
    float ds = d * float(sc);                                                                   \
    float dm = dmin * float(mn);                                                                \
    uint qw = (blk + 16u + g * 32u) >> 2;                                                       \
    [[unroll]] for (uint t = 0u; t < 8u; ++t) {                                                 \
        uint w = qbank[qw + t];                                                                 \
        [[unroll]] for (uint b = 0u; b < 4u; ++b) {                                             \
            uint by = (w >> (8u * b)) & 0xFFu;                                                  \
            uint nib = (sub == 0u) ? (by & 0xFu) : (by >> 4);                                   \
            DST[dst + t * 4u + b] = float16_t(ds * float(nib) - dm);                            \
        }                                                                                       \
    }
#elif QFMT == FMT_Q5_K
#define DEQUANT_BODY(DST)                                                                       \
    uint within = k0 & 255u;                                                                    \
    uint g = within >> 6;                                                                       \
    uint sub = (within >> 5) & 1u;                                                              \
    uint blk = rb + (k0 >> 8) * 176u;                                                           \
    float d = qhalf(blk);                                                                       \
    float dmin = qhalf(blk + 2u);                                                               \
    uint sc, mn;                                                                                \
    scaleMinK4(2u * g + sub, blk + 4u, sc, mn);                                                 \
    float ds = d * float(sc);                                                                   \
    float dm = dmin * float(mn);                                                                \
    uint hmask = (sub == 0u ? 1u : 2u) << (2u * g);                                             \
    uint hw = (blk + 16u) >> 2;                                                                 \
    uint qw = (blk + 48u + g * 32u) >> 2;                                                       \
    [[unroll]] for (uint t = 0u; t < 8u; ++t) {                                                 \
        uint w = qbank[qw + t];                                                                 \
        uint h = qbank[hw + t];                                                                 \
        [[unroll]] for (uint b = 0u; b < 4u; ++b) {                                             \
            uint by = (w >> (8u * b)) & 0xFFu;                                                  \
            uint nib = (sub == 0u) ? (by & 0xFu) : (by >> 4);                                   \
            if ((((h >> (8u * b)) & 0xFFu) & hmask) != 0u) {                                    \
                nib += 16u;                                                                     \
            }                                                                                   \
            DST[dst + t * 4u + b] = float16_t(ds * float(nib) - dm);                            \
        }                                                                                       \
    }
#elif QFMT == FMT_Q5_1
#define DEQUANT_BODY(DST)                                                                       \
    uint blk = rb + (k0 >> 5) * 24u;                                                            \
    float d = qhalf(blk);                                                                       \
    float mn = qhalf(blk + 2u);                                                                 \
    uint qh = qbank[(blk + 4u) >> 2];                                                           \
    uint qw = (blk + 8u) >> 2;                                                                  \
    [[unroll]] for (uint t = 0u; t < 4u; ++t) {                                                 \
        uint w = qbank[qw + t];                                                                 \
        [[unroll]] for (uint b = 0u; b < 4u; ++b) {                                             \
            uint j = t * 4u + b;                                                                \
            uint by = (w >> (8u * b)) & 0xFFu;                                                  \
            uint lo = (by & 0xFu) | (((qh >> j) & 1u) << 4);                                    \
            uint hi = (by >> 4) | (((qh >> (j + 16u)) & 1u) << 4);                               \
            DST[dst + j] = float16_t(float(lo) * d + mn);                                       \
            DST[dst + j + 16u] = float16_t(float(hi) * d + mn);                                 \
        }                                                                                       \
    }
#else
#define DEQUANT_BODY(DST)                                                                       \
    uint blk = rb + (k0 >> 5) * 34u;                                                            \
    float d = qhalf(blk);                                                                       \
    [[unroll]] for (uint j = 0u; j < 32u; ++j) {                                                \
        uint by = qbyte(blk + 2u + j);                                                          \
        DST[dst + j] = float16_t(float(int(by) - int((by >> 7) << 8)) * d);                     \
    }
#endif

DEQUANT_SLAB(dequantB0, sB0)
#if MODE == 0
DEQUANT_SLAB(dequantB1, sB1)
#endif

float sigmoidf(float x) { return 1.0 / (1.0 + exp(-x)); }

void main() {
    uint lane = gl_LocalInvocationID.x;
    uint tileIdx = gl_WorkGroupID.y;
    // Every row block past the schedule's end returns before it reads a
    // weight. The grid is a static upper bound — ceil(tokens*used/BM) plus
    // one partial block per expert — because the real count is only known on
    // the device, and an empty workgroup costs a launch.
    if (tileIdx >= actu[pc.moeTileOff]) {
        return;
    }
    uint rec = pc.moeTileOff + 2u + 3u * tileIdx;
    uint expert = actu[rec];
    uint rowStart = actu[rec + 1u];
    uint rows = actu[rec + 2u];
    uint n0 = gl_WorkGroupID.x * BN;
    uint slots = pc.moeUsed + 1u;

    // Expert e's output row n is bank row e*gemmN + n, which is what makes a
    // three-axis GGUF tensor addressable without a stride table.
    uint bankRow = expert * pc.gemmN + n0 + lane;

    ACC_T acc0[WM][WN];
#if MODE == 0
    ACC_T acc1[WM][WN];
#endif
    [[unroll]] for (uint i = 0u; i < WM; i++) {
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            acc0[i][j] = ACC_T(0.0);
#if MODE == 0
            acc1[i][j] = ACC_T(0.0);
#endif
        }
    }

    for (uint k0 = 0u; k0 < pc.gemmK; k0 += BK) {
#if MODE == 0
        // The A operand is gathered: BM rows of the block input, named by the
        // permutation and belonging to BM different tokens.
        for (uint idx = lane; idx < BM * BK; idx += WAVE) {
            uint r = idx / BK;
            uint c = idx - r * BK;
            float16_t v = float16_t(0.0);
            if (r < rows) {
                uint p = actu[pc.moePermOff + rowStart + r];
                v = hact[pc.xnOff + (p / slots) * pc.lda + k0 + c];
            }
            sA[r * LDS_ROW + c] = v;
        }
        dequantB0(pc.bOff, bankRow, k0, lane);
        dequantB1(pc.moeBOff2, bankRow, k0, lane);
#else
        dequantB0(pc.bOff, bankRow, k0, lane);
#endif
        barrier();

        [[unroll]] for (uint kt = 0u; kt < BK_TILES; kt++) {
            FRAG_A_T fragA[WM];
            [[unroll]] for (uint i = 0u; i < WM; i++) {
#if MODE == 0
                coopMatLoad(fragA[i], sA, (i * TILE) * LDS_ROW + kt * TILE, LDS_ROW,
                    gl_CooperativeMatrixLayoutRowMajor);
#else
                // MODE 1's rows are permutation positions and so contiguous:
                // no gather, and the overhang past this expert reads the next
                // one's swiglu rows and is thrown away at the store.
                coopMatLoad(fragA[i], hact,
                    pc.ctxOff + (rowStart + i * TILE) * pc.ldCtx + k0 + kt * TILE, pc.ldCtx,
                    gl_CooperativeMatrixLayoutRowMajor);
#endif
            }
            [[unroll]] for (uint j = 0u; j < WN; j++) {
                FRAG_B_T fragB;
                coopMatLoad(fragB, sB0, (j * TILE) * LDS_ROW + kt * TILE, LDS_ROW,
                    gl_CooperativeMatrixLayoutColumnMajor);
                [[unroll]] for (uint i = 0u; i < WM; i++) {
                    acc0[i][j] = coopMatMulAdd(fragA[i], fragB, acc0[i][j]);
                }
#if MODE == 0
                coopMatLoad(fragB, sB1, (j * TILE) * LDS_ROW + kt * TILE, LDS_ROW,
                    gl_CooperativeMatrixLayoutColumnMajor);
                [[unroll]] for (uint i = 0u; i < WM; i++) {
                    acc1[i][j] = coopMatMulAdd(fragA[i], fragB, acc1[i][j]);
                }
#endif
            }
        }
        barrier();
    }

    // ---- The epilogue, through LDS because the tail of a tile must not
    // write. MODE 0 applies `ggml_swiglu_split(gate, up)` = silu(gate)*up on
    // the accumulators first, so the [rows, ffn] pair the reference
    // materialises never exists.
    [[unroll]] for (uint i = 0u; i < WM; i++) {
        [[unroll]] for (uint j = 0u; j < WN; j++) {
#if MODE == 0
            ACC_T sw;
            [[unroll]] for (uint e = 0u; e < acc0[i][j].length(); e++) {
                float g = float(acc0[i][j][e]);
                sw[e] = g * sigmoidf(g) * float(acc1[i][j][e]);
            }
            coopMatStore(sw, sC, (i * TILE) * BN + j * TILE, BN,
                gl_CooperativeMatrixLayoutRowMajor);
#else
            coopMatStore(acc0[i][j], sC, (i * TILE) * BN + j * TILE, BN,
                gl_CooperativeMatrixLayoutRowMajor);
#endif
        }
    }
    barrier();

    for (uint r = 0u; r < rows; ++r) {
#if MODE == 0
        uint dst = pc.ctxOff + (rowStart + r) * pc.ldCtx + n0;
        for (uint c = lane; c < BN; c += WAVE) {
            hact[dst + c] = float16_t(sC[r * BN + c]);
        }
#else
        // The scatter and the routing weight, in the store that had to
        // happen anyway: `ffn_moe_weighted` is never a tensor.
        uint p = actu[pc.moePermOff + rowStart + r];
        float wt = act[pc.moeWeightOff + p];
        uint dst = pc.gatedOff + p * pc.nEmbd + n0;
        for (uint c = lane; c < BN; c += WAVE) {
            act[dst + c] = sC[r * BN + c] * wt;
        }
#endif
    }
}

