#version 450

#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
#extension GL_EXT_control_flow_attributes : require

// `ffn_out` — the ten routed contributions and the shared expert's, summed
// (LLM.md L5b).
//
// It exists because the down projection cannot accumulate in place. A token's
// ten experts are ten different tiles of the grouped GEMM, so without a
// float atomic each writes its own row and something has to add them up. What
// makes that cheap rather than merely necessary is the permutation's own
// indexing: a row is `token * (used + 1) + slot`, so a token's eleven
// contributions are **contiguous** and this kernel reads them as a run rather
// than gathering through the selection.
//
// The order is the reference's: the ten in slot order, then
// `ffn_shexp_gated`, which is the chain of adds `build_layer_ffn` emits and
// the order `moe.go`'s CPU reference sums in.

#include "llm_common.glsl"

#define WG 256

layout(local_size_x = WG) in;

void main() {
    uint t = gl_WorkGroupID.x;
    if (t >= pc.tokens) {
        return;
    }
    uint slots = pc.moeUsed + 1u;
    uint src = pc.gatedOff + t * slots * pc.nEmbd;
    uint dst = pc.outOff + t * pc.nEmbd;
    for (uint j = gl_LocalInvocationID.x; j < pc.nEmbd; j += WG) {
        float s = 0.0;
        for (uint k = 0u; k < slots; ++k) {
            s += act[src + k * pc.nEmbd + j];
        }
        act[dst + j] = s;
    }
}

