9	// The routing permutation and the tile schedule it implies (LLM.md L5b).
10	//
11	// A counting sort over the 512 experts: histogram, exclusive prefix sum,
12	// scatter. It is one workgroup because the whole input is `tokens * used`
13	// integers — 5120 at a 512-token ubatch, 40 960 at the 4 k fixture — and
14	// 97% of this block's time is in the two GEMMs behind it.
15	//
16	// **L5a-4 is why the schedule is a list and not a grid.** At a 512-token
17	// ubatch only **274 of 512 experts are touched**, one of them takes **484 of
18	// the 512 tokens** and 273 of the other 273 have fewer than 19: a workgroup
19	// per expert has a 26x load imbalance and a grid of (experts x fixed row
20	// blocks) is almost entirely empty. So this kernel emits one record per
21	// (expert, row block) that actually has rows — `tileCount` of them — and the
22	// GEMM dispatches a static upper bound of `ceil(tokens*used/BM) + nExperts`
23	// row blocks, every one past `tileCount` returning before it reads anything.
24	// The bound is tight because an expert wastes at most one partial block.
25	//
26	// The padding that bound describes is not free arithmetic, but it is nearly
27	// free time: a cold expert's tile executes BM rows where 17 are real, and
28	// that tile is reading 0.9 MB of Q4_K to do it. The waste is ~1.8x of the
29	// *rows* at ubatch 512 and 1.17x at 4096, and it lands where the kernel is
30	// bound by weight bytes rather than by the matrix cores.
31	//
32	// Two things it deliberately does not promise. The order of rows **within**
33	// an expert is whatever the scatter's atomics give, because every row is
34	// independent and the combine sums by (token, slot): the block's output is
35	// order-independent even though this array is not. And the row a permutation
36	// entry names is `token * (used + 1) + slot`, not the token — so the slot
37	// stride carries the shared expert's row as its last element and the combine
38	// reads a token's eleven contributions as one contiguous run.
39	
40	#include "llm_common.glsl"
41	
42	#define WG 256
43	#define MAX_EXPERTS 512
44	
45	layout(local_size_x = WG) in;
46	
47	shared uint shCnt[MAX_EXPERTS];
48	shared uint shWave[WG / 64];
49	
50	void main() {
51	    uint tid = gl_LocalInvocationID.x;
52	    uint nE = pc.gemmK;          // the expert count
53	    uint used = pc.moeUsed;
54	    uint slots = used + 1u;
55	    uint pairs = pc.tokens * used;
56	    uint bm = pc.gemmM;          // the row block the tile list is cut to
57	    uint sg = tid / 64u;
58	
59	    // The bookkeeping lives immediately past the permutation, which is
60	    // exactly `pairs` entries: a tile overhangs its expert's rows in the
61	    // *swiglu* buffer, which the guarded store throws away, but it never
62	    // reads a permutation entry past the row count it was given.
63	    uint book = pc.moePermOff + pairs;
64	    uint counts = book;
65	    uint offsets = book + nE;
66	    uint cursor = book + 2u * nE;
67	    uint tileBase = book + 3u * nE;
68	    uint topk = pc.moeWeightOff + pc.tokens * slots;
69	
70	    for (uint e = tid; e < nE; e += WG) {
71	        actu[counts + e] = 0u;
72	    }
73	    barrier();
74	
75	    // ---- The histogram.
76	    for (uint p = tid; p < pairs; p += WG) {
77	        atomicAdd(actu[counts + actu[topk + p]], 1u);
78	    }
79	    barrier();
80	
81	    // ---- Two exclusive prefix sums over the experts, in the same shape: one
82	    // over the counts, which is where an expert's rows start, and one over
83	    // ceil(count/BM), which is where its tile records start. A subgroup scan
84	    // per wave, the wave totals carried across, and a carry across the
85	    // chunks — because nE is 512 and the workgroup is 256.
86	    uint carryRows = 0u;
87	    uint carryTiles = 0u;
88	    for (uint c0 = 0u; c0 < MAX_EXPERTS; c0 += WG) {
89	        uint e = c0 + tid;
90	        uint cnt = (e < nE) ? actu[counts + e] : 0u;
91	        shCnt[min(e, MAX_EXPERTS - 1u)] = cnt;
92	        uint nt = (cnt + bm - 1u) / bm;
93	
94	        uint rowTot = subgroupAdd(cnt);
95	        uint rowEx = subgroupExclusiveAdd(cnt);
96	        uint tileTot = subgroupAdd(nt);
97	        uint tileEx = subgroupExclusiveAdd(nt);
98	        if (subgroupElect()) {
99	            shWave[sg] = rowTot;
100	        }
101	        barrier();
102	        uint rowBefore = 0u, rowAll = 0u;
103	        [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
104	            rowAll += shWave[w];
105	            if (w < sg) {
106	                rowBefore += shWave[w];
107	            }
108	        }
109	        barrier();
110	        if (subgroupElect()) {
111	            shWave[sg] = tileTot;
112	        }
113	        barrier();
114	        uint tileBefore = 0u, tileAll = 0u;
115	        [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
116	            tileAll += shWave[w];
117	            if (w < sg) {
118	                tileBefore += shWave[w];
119	            }
120	        }
121	        barrier();
122	
123	        if (e < nE) {
124	            uint off = carryRows + rowBefore + rowEx;
125	            actu[offsets + e] = off;
126	            actu[cursor + e] = off;
127	            actu[tileBase + e] = carryTiles + tileBefore + tileEx;
128	        }
129	        carryRows += rowAll;
130	        carryTiles += tileAll;
131	    }
132	    if (tid == 0u) {
133	        actu[pc.moeTileOff] = carryTiles;
134	        actu[pc.moeTileOff + 1u] = carryRows;
135	    }
136	    barrier();
137	
138	    // ---- The scatter. `p` is (token, slot) flattened by `used`; what lands
139	    // in the permutation is the same pair flattened by `used + 1`, so the
140	    // shared expert's slot is already spoken for.
141	    for (uint p = tid; p < pairs; p += WG) {
142	        uint e = actu[topk + p];
143	        uint idx = atomicAdd(actu[cursor + e], 1u);
144	        uint tok = p / used;
145	        uint k = p - tok * used;
146	        actu[pc.moePermOff + idx] = tok * slots + k;
147	    }
148	
149	    // ---- The tile records: expert, first row, and how many of BM are real.
150	    // Written from the counts in LDS, so the scatter above and this loop do
151	    // not contend for the same cache lines.
152	    for (uint e = tid; e < nE; e += WG) {
153	        uint cnt = shCnt[e];
154	        uint off = actu[offsets + e];
155	        uint tb = actu[tileBase + e];
156	        for (uint mb = 0u; mb * bm < cnt; ++mb) {
157	            uint rec = pc.moeTileOff + 2u + 3u * (tb + mb);
158	            actu[rec] = e;
159	            actu[rec + 1u] = off + mb * bm;
160	            actu[rec + 2u] = min(bm, cnt - mb * bm);
161	        }
162	    }
163	}

