#version 450

#extension GL_KHR_shader_subgroup_basic : require
#extension GL_KHR_shader_subgroup_arithmetic : require
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
#extension GL_EXT_control_flow_attributes : require

// The routing permutation and the tile schedule it implies (LLM.md L5b).
//
// A counting sort over the 512 experts: histogram, exclusive prefix sum,
// scatter. It is one workgroup because the whole input is `tokens * used`
// integers — 5120 at a 512-token ubatch, 40 960 at the 4 k fixture — and
// 97% of this block's time is in the two GEMMs behind it.
//
// **L5a-4 is why the schedule is a list and not a grid.** At a 512-token
// ubatch only **274 of 512 experts are touched**, one of them takes **484 of
// the 512 tokens** and 273 of the other 273 have fewer than 19: a workgroup
// per expert has a 26x load imbalance and a grid of (experts x fixed row
// blocks) is almost entirely empty. So this kernel emits one record per
// (expert, row block) that actually has rows — `tileCount` of them — and the
// GEMM dispatches a static upper bound of `ceil(tokens*used/BM) + nExperts`
// row blocks, every one past `tileCount` returning before it reads anything.
// The bound is tight because an expert wastes at most one partial block.
//
// The padding that bound describes is not free arithmetic, but it is nearly
// free time: a cold expert's tile executes BM rows where 17 are real, and
// that tile is reading 0.9 MB of Q4_K to do it. The waste is ~1.8x of the
// *rows* at ubatch 512 and 1.17x at 4096, and it lands where the kernel is
// bound by weight bytes rather than by the matrix cores.
//
// Two things it deliberately does not promise. The order of rows **within**
// an expert is whatever the scatter's atomics give, because every row is
// independent and the combine sums by (token, slot): the block's output is
// order-independent even though this array is not. And the row a permutation
// entry names is `token * (used + 1) + slot`, not the token — so the slot
// stride carries the shared expert's row as its last element and the combine
// reads a token's eleven contributions as one contiguous run.

#include "llm_common.glsl"

#define WG 256
#define MAX_EXPERTS 512

layout(local_size_x = WG) in;

shared uint shCnt[MAX_EXPERTS];
shared uint shWave[WG / 64];

void main() {
    uint tid = gl_LocalInvocationID.x;
    uint nE = pc.gemmK;          // the expert count
    uint used = pc.moeUsed;
    uint slots = used + 1u;
    uint pairs = pc.tokens * used;
    uint bm = pc.gemmM;          // the row block the tile list is cut to
    uint sg = tid / 64u;

    // The bookkeeping lives immediately past the permutation, which is
    // exactly `pairs` entries: a tile overhangs its expert's rows in the
    // *swiglu* buffer, which the guarded store throws away, but it never
    // reads a permutation entry past the row count it was given.
    uint book = pc.moePermOff + pairs;
    uint counts = book;
    uint offsets = book + nE;
    uint cursor = book + 2u * nE;
    uint tileBase = book + 3u * nE;
    uint topk = pc.moeWeightOff + pc.tokens * slots;

    for (uint e = tid; e < nE; e += WG) {
        actu[counts + e] = 0u;
    }
    barrier();

    // ---- The histogram.
    for (uint p = tid; p < pairs; p += WG) {
        atomicAdd(actu[counts + actu[topk + p]], 1u);
    }
    barrier();

    // ---- Two exclusive prefix sums over the experts, in the same shape: one
    // over the counts, which is where an expert's rows start, and one over
    // ceil(count/BM), which is where its tile records start. A subgroup scan
    // per wave, the wave totals carried across, and a carry across the
    // chunks — because nE is 512 and the workgroup is 256.
    uint carryRows = 0u;
    uint carryTiles = 0u;
    for (uint c0 = 0u; c0 < MAX_EXPERTS; c0 += WG) {
        uint e = c0 + tid;
        uint cnt = (e < nE) ? actu[counts + e] : 0u;
        shCnt[min(e, MAX_EXPERTS - 1u)] = cnt;
        uint nt = (cnt + bm - 1u) / bm;

        uint rowTot = subgroupAdd(cnt);
        uint rowEx = subgroupExclusiveAdd(cnt);
        uint tileTot = subgroupAdd(nt);
        uint tileEx = subgroupExclusiveAdd(nt);
        if (subgroupElect()) {
            shWave[sg] = rowTot;
        }
        barrier();
        uint rowBefore = 0u, rowAll = 0u;
        [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
            rowAll += shWave[w];
            if (w < sg) {
                rowBefore += shWave[w];
            }
        }
        barrier();
        if (subgroupElect()) {
            shWave[sg] = tileTot;
        }
        barrier();
        uint tileBefore = 0u, tileAll = 0u;
        [[unroll]] for (uint w = 0u; w < WG / 64u; ++w) {
            tileAll += shWave[w];
            if (w < sg) {
                tileBefore += shWave[w];
            }
        }
        barrier();

        if (e < nE) {
            uint off = carryRows + rowBefore + rowEx;
            actu[offsets + e] = off;
            actu[cursor + e] = off;
            actu[tileBase + e] = carryTiles + tileBefore + tileEx;
        }
        carryRows += rowAll;
        carryTiles += tileAll;
    }
    if (tid == 0u) {
        actu[pc.moeTileOff] = carryTiles;
        actu[pc.moeTileOff + 1u] = carryRows;
    }
    barrier();

    // ---- The scatter. `p` is (token, slot) flattened by `used`; what lands
    // in the permutation is the same pair flattened by `used + 1`, so the
    // shared expert's slot is already spoken for.
    for (uint p = tid; p < pairs; p += WG) {
        uint e = actu[topk + p];
        uint idx = atomicAdd(actu[cursor + e], 1u);
        uint tok = p / used;
        uint k = p - tok * used;
        actu[pc.moePermOff + idx] = tok * slots + k;
    }

    // ---- The tile records: expert, first row, and how many of BM are real.
    // Written from the counts in LDS, so the scatter above and this loop do
    // not contend for the same cache lines.
    for (uint e = tid; e < nE; e += WG) {
        uint cnt = shCnt[e];
        uint off = actu[offsets + e];
        uint tb = actu[tileBase + e];
        for (uint mb = 0u; mb * bm < cnt; ++mb) {
            uint rec = pc.moeTileOff + 2u + 3u * (tb + mb);
            actu[rec] = e;
            actu[rec + 1u] = off + mb * bm;
            actu[rec + 2u] = min(bm, cnt - mb * bm);
        }
    }
}

